// Custom Worker entry: OpenNext handles HTTP; we add (1) per-language URLs (/ar /fr /en) and (2) a Cron handler for carrier tracking + push campaigns.
// @ts-expect-error generated by `opennextjs-cloudflare build`
import openNext from "./.open-next/worker.js";
import { edgeBlock } from "./src/features/visitors/edge-block";

type Env = { ASSETS: Fetcher; DB?: D1Database; SECRETS_KEY?: string } & Record<string, unknown>;

const LANG = /^\/([a-z]{2})(?=\/|$)/; // two-letter language codes; the app answers 404 for ones the store does not have
/** Paths that are not pages: never prefixed, never language-switched. */
const NOT_PAGE = /^\/(_next|api|files|admin|setup|pwa|sw\.js|manifest\.webmanifest|sitemap|robots\.txt|accept-invite|favicon)/;

const withCookie = (header: string | null, name: string, value: string) =>
  [...(header ?? "").split(/;\s*/).filter((c) => c && !c.startsWith(`${name}=`)), `${name}=${value}`].join("; ");

function prefixed(lang: string, href: string): string {
  if (!href.startsWith("/") || href.startsWith("//") || NOT_PAGE.test(href) || LANG.test(href)) return href;
  return href === "/" ? `/${lang}` : `/${lang}${href}`;
}

async function serve(request: Request, env: Env, ctx: ExecutionContext): Promise<Response> {
  const url = new URL(request.url);
  const m = LANG.exec(url.pathname);
  const lang = m?.[1];
  const path = lang ? url.pathname.slice(3) || "/" : url.pathname;
  const isPage = !NOT_PAGE.test(path);
  // blocked visitors never reach the app: one in-memory lookup, no per-request database query
  const blocked = await edgeBlock(request, path, env, ctx);
  if (blocked) return blocked;
  const headers = new Headers(request.headers);
  headers.set("x-seo-path", path); // always set here, so a client can't forge it
  headers.delete("x-seo-lang");
  if (lang && isPage) headers.set("x-seo-lang", lang);
  if (lang && isPage) headers.set("cookie", withCookie(headers.get("cookie"), "lang", lang));
  if (!lang && !m && !isPage) return openNext.fetch(request, env, ctx);
  url.pathname = path;
  const init = { method: request.method, headers, redirect: "manual", cf: (request as unknown as { cf?: unknown }).cf, duplex: "half",
    body: request.method === "GET" || request.method === "HEAD" ? undefined : request.body } as RequestInit;
  const res: Response = await openNext.fetch(new Request(url.toString(), init), env, ctx);
  if (!lang || !isPage) return res;

  const out = new Headers(res.headers);
  const loc = out.get("location");
  if (loc && loc.startsWith("/")) out.set("location", prefixed(lang, loc));
  out.append("set-cookie", `lang=${lang}; Path=/; Max-Age=31536000; SameSite=Lax`);
  const base = new Response(res.body, { status: res.status, statusText: res.statusText, headers: out });
  if (!(out.get("content-type") ?? "").includes("text/html")) return base;
  // crawlers and middle-click follow the DOM, so keep them on the language's own URLs
  return new HTMLRewriter()
    .on("a[href]", { element(e) { const h = e.getAttribute("href"); if (h) e.setAttribute("href", prefixed(lang, h)); } })
    .on("form[action]", { element(e) { const h = e.getAttribute("action"); if (h) e.setAttribute("action", prefixed(lang, h)); } })
    .transform(base);
}


/* The `caches.default` page cache that used to sit here never produced a hit on this platform (every response was a MISS), so it only
 * added a lookup, a body clone and a cache write to each request. Pages are served straight from the app. */
const handle = serve;

export default {
  fetch: handle,
  async scheduled(_event: ScheduledController, env: Env, ctx: ExecutionContext) {
    // Call our own route handler so the sync runs in the full app runtime.
    const req = new Request("https://internal/api/cron/sync-tracking", {
      method: "POST",
      headers: { "x-cron": "1" },
    });
    ctx.waitUntil(openNext.fetch(req, env, ctx));
  },
};

// Durable Object classes OpenNext's bundle expects to be exported (unused unless bound).
// @ts-expect-error generated by `opennextjs-cloudflare build`
export { DOQueueHandler, DOShardedTagCache, BucketCachePurge } from "./.open-next/worker.js";
